INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (58, 324, 'Polyester based Thermal Lamination Film', '../', '<p></p><h2> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Polyester based Thermal Lamination Film</span> </h2> <p><b><span style=''font-family:"";''></span></b><b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"></span></b></p> <p style="text-align:justify;"> <b><span style="color:#E53333;font-family:Tahoma;font-size:18px;">PROFILE </span></b><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">: It is polyester based, both sides corona treated, uniformly extrusion coated with adhesive which enables lamination by heat and pressure with paper products.</span></span></p> <p style="text-align:justify;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"></span></p> <p><b><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">FEATURES</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">:</span></span></b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"></span></p> <p style="text-indent:-21.75pt;"> <span style=''font-family:"";''><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1)</span></span></span><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Fibre-tear bond strength with paper</span></span></p> <p><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">2) Excellent optical properties. </span></span></p> <p><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">3) Excellent resistance to elongation &amp; tear.</span></span></p> <p><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">4) Offer increased productivity with simple operation.</span></span></p> <p></p> <p><b><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">APPLICATIONS :</span></span></b><span style=''font-family:"font-size:11pt;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Thermal lamination with all kinds of printed &amp; unprinted paper and paper boards like maps, book covers,</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">posters, magazines, boxes, brochures etc.</span></span></p> <p></p> <p><span style=''font-family:"";''></span></p> <p><b><span style="color:#E53333;font-family:Tahoma;font-size:18px;">TYPICAL PROPERTIES:</span></b></p> <table border="1" cellpadding="0" cellspacing="0" style="margin:auto auto auto 9.9pt;border:currentColor;border-collapse:collapse;" width="600"> <tbody> <tr> <td style="border:1pt solid windowtext;background-color:transparent;" valign="top" width="216"> <p><b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span>PROPERTY</span></span></b></p> </td> <td style="background-color:transparent;" valign="top" width="150"> <p align="center" style="text-align:center;"> <b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span>UNIT</span></span></b></p> </td> <td style="background-color:transparent;" valign="top" width="126"> <p align="center" style="text-align:center;"> <b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span>ASTM/ TEST #</span></span></b></p> </td> <td style="background-color:transparent;" valign="top" width="108"> <p align="center" style="text-align:center;"> <b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span>30 PCT-2</span></span></b></p> <p align="center" style="text-align:center;"> <b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span>(PDL)</span></span></b></p> </td> </tr> <tr> <td style="background-color:transparent;" valign="top" width="216"> <p><br/></p><p><b><span style="color:#E53333;font-family:Tahoma;font-size:18px;">PHYSICAL DATA</span></b></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Average Thickness</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Average GSM</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Yield</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Wettability (min)</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Coefficient of friction (F-F)</span></p> <p><b><span style="color:#E53333;font-family:Tahoma;font-size:18px;">OPTICAL DATA</span></b></p> <p><span style=''font-family:"font-size:11pt;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Gloss</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">at 45 </span><sup><span style="color:#E53333;font-family:Tahoma;font-size:18px;">0 </span></sup><span style="color:#E53333;font-family:Tahoma;font-size:18px;">(min)</span></span></p> <p><br/></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Lamination temp. </span></p> </td> <td style="background-color:transparent;" valign="top" width="150"> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">micron</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">(+/-) %</span></p> <p align="center" style="text-align:center;"> <span style=''font-family:"font-size:11pt;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">m</span><sup><span style="color:#E53333;font-family:Tahoma;font-size:18px;">2 </span></sup><span style="color:#E53333;font-family:Tahoma;font-size:18px;">/kg</span></span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">dynes/cm</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">-----</span></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">gardner</span></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p><span style=''font-family:"font-size:11pt;''><sup><span style="color:#E53333;font-family:Tahoma;font-size:18px;">O</span></sup><span style="color:#E53333;font-family:Tahoma;font-size:18px;">C</span></span></p> <p></p> </td> <td style="background-color:transparent;" valign="top" width="126"> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">D-374-C</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">---</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">--</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">D-2578</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">D-1894</span></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">D-2457</span></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> </td> <td style="background-color:transparent;" valign="top" width="108"> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">30.0</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">34.80</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">28.73</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">40</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">0.25</span></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">95</span></p> <p align="center" style="text-align:center;"> <b></b></p> <p></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">90 - 150</span></p> </td> </tr> </tbody> </table> <p><b></b></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">_____________________________________________________________</span></p> <p></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (58, 176, 'Acrylic acid coating film', '../upload/image/20180826/20180826131109_71020.jpg', '<p></p><p>Acrylic acid coating film</p> <p>1. ACRYLIC ACID COATING BOPP FILM<br/> Acrylic coated BOPP film on one or two side(s) with a detailed description of:<br/> BOPP acrylic films were based on BOPP film, coated on one or two side(s) with acrylic. Wide range of uses, especially suitable for the packaging of biscuits and other snack products ; suitable for food boxes, medicine boxes, perfume boxes, cosmetic boxes. <br/> Main performance for Crylic acid coating film:<br/> a.) excellent packaging adaptability, low coefficient of friction of the coating and stability; <br/> b.) excellent low-temperature heat sealing properties, outstanding transparency properties; <br/> c.) applicable to various ink printing, including water-based inks<br/> Thickness: 20 30 Microns...<br/> Width: 120-1500MM Length: 200-4000M Inner core:1" 2" 3" 6". <br/> 2. ACRYLIC ACID COATING BOPET FILM<br/> Acrylic coated BOPET film on one or two side(s) with a detailed description of:<br/> The film is PET acrylic coating film to the substrate, the single-sided coating of acrylic. Particularly suitable for the packaging of biscuits and other snack products Bao-Xiang; also suitable for food boxes, medicine boxes, perfume boxes, cosmetic boxes. <br/> Main performance for Acrylic acid coating film<br/> a.) excellent packaging adaptability, low coefficient of friction of the coating and stability; <br/> b.) excellent low-temperature heat sealing properties, outstanding transparency properties; <br/> c.) applicable to various ink printing, including water-based inks.<br/> Thickness: 14.1 17.1 Microns...<br/> Width: 120-1500MM Length: 200-4000M Inner core:1" 2" 3" 6".</p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (58, 172, 'BOPP/BOPET/BOPA Thermal Lamination Film (glossy and matte lamination)', '../upload/image/20180928/20180928231652_54813.jpg', '<p></p><p>BOPP/BOPET/BOPA Thermal Lamination Film (glossy and matte lamination)</p> <p>BOPP/BOPET/BOPA Thermal Lamination Film (glossy/matte) which were BOPP clear film coated with EVA.<br/> Spec.: 1.) Jumbo roll sizes: <br/> Total Thickness: 22-33UM (Mic.)<br/> Basic film thickness: 10,12,15,18,20 UM (Mic.) Width :325-1200MM<br/> Length:3000M (2000M,4000M,6000M,9000M).Inner core:76MM ,152MM 2.) Mini-roll sizes:Total Thickness :22-33UM (Mic.) Film thickness: 10,12,15,18,20 UM (Mic.) Width :325-1200MM<br/> Type:included BOPET thermal film (Polyester thermal lamination film with EVA),BOPA thermal film (nylon<br/> thermal lamination film with EVA), bopp thermal film (Polypropylene thermal lamination film with EVA)<br/> Length :100M,120M,150M,200M Inner core :1.5",1.8", 2.0",3" (Inches)<br/> Applications:Laminate the surface of Books, catalogs, samples, posters, printed paper, Food, medicines, cosmetics, gifts, wine boxes and other packaging film ,Drawings, documents, ads, pictures, display boards, etc.</p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (58, 118, 'Soft-touch velvet BOPP thermal laminating film with EVA adhesive coating &amp;soft touch oil', '../upload/image/20180922/20180922163806_86819.jpg', '<p></p><p>Soft-touch velvet BOPP thermal laminating film with EVA adhesive coating &amp;soft touch oil<br/> Tactile membrane (SoftTouch Film), is a latest research results from the European BOPP laminating film special. This patented technology has the film factory, only production of BOPP film products, and has over 20 years of professional experience. Is a surface with special velvet smooth, delicate touch of BOPP matte film.<br/> Categories Folding<br/> Depending on the coating method can be divided into CM017WE not touch the film adhesive film (Wet), CM035EA pre-coated hot melt adhesive film (Thermal), as well as pre-coated hot melt adhesive film with digital printing three.<br/> Feature<br/> Tactile membrane (SoftTouch Film) compared with the general Asian film, tactile membrane (SoftTouch Film), has the following four characteristics:<br/> 1. has a good abrasion (ANTI-SCRATCH) performance;<br/> 2. Excellent color, hue is not lost after the fit, the more bright and pastel on black and red with dark field or large full version;<br/> 3. There is a special smooth as velvet, delicate touch;<br/> 4. high fog, there are more special matt effect.<br/> Compared with the new touch membrane touch paper<br/> The new film and paper touch after touch fitting can be achieved with paper-haptic effects; but in the adaptability and characteristic features, can bring more results. Include the following:<br/> 1. The new film can touch any surface with a smooth fit paper, coated paper or uncoated paper, culture paper or long staple fibers cultural paper, colored paper or printing paper, which can be used as basis for the composite end paper,<br/> 2. The new tactile membrane attached together before the end of the paper can be in any way an ordinary four-color offset printing, flexo, gravure, letterpress, screen printing or digital inkjet printing, there is no restriction on the printed pattern, you can also fit after in the new touch membrane surface bronzing, local polishing, screen printing, UV printing and other post-processing technology, in bookbinding or carton forming process can also play a role in better protection.<br/> 3. The new velvet touch surface of the membrane tactile effects, smoother than the touch paper come. Delicate, by contrast, it seems to be rather dry touch paper. In addition, if fingerprints are on the surface of infected, new tactile membrane can be easily wiped off with water.<br/> Purpose Folding<br/> In the film''s use of touch, using hot lamination or coating after drying water-based glue lamination technology, the new film is bonded to touch the paper surface, so as to achieve a smooth soft-touch feel special, and has a high transparency, ensuring no blind spots in lost after lamination. This technology is suitable for luxury boxes, Advanced Book covers, paper products and other brands. In art printing industry widely used.<br/> is designed to offer soft tactility velvet touch to printed substrate. It can be attached to any surface smooth paper printed by various printing types. Its velvet surface is suitable for UV spot coating, foil stamping to enhance its aesthetic look.<br/> General Applications<br/> ·High-value Packaging<br/> ·User manuals<br/> ·Promotion stuff<br/> ·Leaflets<br/> Usage Method<br/> 1) for laminating soft-touch film<br/> Laminating temperature: 120 ℃ ~130 ℃<br/> 2) for glue-coating soft-touch film<br/> Check the gloss surface energy to insure that it is suitable for glue coating. Choose suitable glue and flatten the film to get perfect attaching effect.</p> <p><img alt="" src="../upload/image/20180824/20180824213538_26776.jpg"/><img alt="" src="../upload/image/20180824/20180824213538_47023.jpg"/><img alt="" src="../upload/image/20180824/20180824213538_25575.jpg"/><img alt="" src="../upload/image/20180824/20180824213538_64091.jpg"/><img alt="" src="../upload/image/20180824/20180824213538_64835.jpg"/><img alt="" src="../upload/image/20180824/20180824213540_92323.jpg"/><img alt="" src="../upload/image/20180824/20180824213540_89942.jpg"/><img alt="" src="../upload/image/20180824/20180824213540_24158.jpg"/><img alt="" src="../upload/image/20180824/20180824213540_73393.jpg"/><img alt="" src="../upload/image/20180824/20180824213540_75733.jpg"/><img alt="" src="../upload/image/20180824/20180824213541_96476.jpg"/><img alt="" src="../upload/image/20180824/20180824213541_92232.jpg"/><img alt="" src="../upload/image/20180824/20180824213541_92158.jpg"/></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (58, 235, 'BOPET Thermal Lamination Film', '../upload/image/20180928/20180928231805_76508.jpg', '<p><strong><span style=''color:#FF0000;line-height:27px;font-family:Calibri, "font-size:24px;vertical-align:baseline;background-color:#FFFF00;''>BOPET Thermal Lamination Film </span></strong></p><p align="left" style="color:#333333;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"> <strong><span style=''color:#FF0000;line-height:36px;font-family:Calibri, "font-size:24px;background-color:#FFFF00;''><span style="line-height:18px;vertical-align:baseline;"><span style="line-height:24px;vertical-align:baseline;">Application:</span></span> Laminating film can be applied to various types of materials such as ID cards,cultural and historical</span></strong></p> <p align="left" style="color:#333333;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"> <strong><span style=''color:#FF0000;line-height:36px;font-family:Calibri, "font-size:24px;background-color:#FFFF00;''> documents,credit cards,licenses,business certificates.</span></strong></p> <p align="left" style="color:#333333;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"> <strong></strong></p> <p align="left" style="color:#333333;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"> <strong><span style=''color:#FF0000;line-height:36px;font-family:Calibri, "font-size:24px;background-color:#FFFF00;''><span style="line-height:24px;vertical-align:baseline;"><span style="vertical-align:baseline;">Main property: </span></span> <span style="line-height:21px;vertical-align:baseline;"> low heat shrinkage,good ink and metal adhesion</span></span></strong></p> <p align="left" style="color:#333333;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"> <strong><span style=''color:#FF0000;line-height:36px;font-family:Calibri, "font-size:24px;background-color:#FFFF00;''> <span style="line-height:21px;vertical-align:baseline;"> good dimensional stability,excellent processing ability</span></span></strong></p> <p style="color:#3A3A3A;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:Arial, Helvetica;font-size:12px;font-style:normal;font-weight:normal;vertical-align:baseline;background-color:#FFFFFF;"> <span style="line-height:18px;background-color:#FFFF00;