INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (58, 234, 'ACRYLIC ACID COATING BOPP FILM', '../upload/image/20180826/20180826183413_28503.jpg', '<p><span style="color:#3A3A3A;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">crylic acid coating film</span></p><p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> 1. ACRYLIC ACID COATING BOPP FILM<br/> Acrylic coated BOPP film on one or two side(s) with a detailed description of:<br/> BOPP acrylic films were based on BOPP film, coated on one or two side(s) with acrylic. Wide range of <br/> uses, especially suitable for the packaging of biscuits and other snack products ; suitable for food boxes, <br/> medicine boxes, perfume boxes, cosmetic boxes. <br/> Main performance for Crylic acid coating film:<br/> a.) excellent packaging adaptability, low coefficient of friction of the coating and stability; <br/> b.) excellent low-temperature heat sealing properties, outstanding transparency properties; <br/> c.) applicable to various ink printing, including water-based inks<br/> Thickness: 20 30 Microns...<br/> Width: 120-1500MM Length: 200-4000M Inner core:1" 2" 3" 6". <br/> 2. ACRYLIC ACID COATING BOPET FILM<br/> Acrylic coated BOPET film on one or two side(s) with a detailed description of:<br/> The film is PET acrylic coating film to the substrate, the single-sided coating of acrylic. Particularly <br/> suitable for the packaging of biscuits and other snack products Bao-Xiang; also suitable for food boxes, <br/> medicine boxes, perfume boxes, cosmetic boxes. <br/> Main performance for Acrylic acid coating film<br/> a.) excellent packaging adaptability, low coefficient of friction of the coating and stability; <br/> b.) excellent low-temperature heat sealing properties, outstanding transparency properties; <br/> c.) applicable to various ink printing, including water-based inks.<br/> Thickness: 14.1 17.1 Microns...<br/> Width: 120-1500MM Length: 200-4000M Inner core:1" 2" 3" 6".</p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <br/></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''line-height:24px;font-family:Calibri, "zapf dingbats";font-size:16px;''>2. Usage</span></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''line-height:24px;font-family:Calibri, "zapf dingbats";font-size:16px;''>It is widely used in packaging industry such as printing, lamination and Aluminium metallization. </span></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''line-height:24px;font-family:Calibri, "zapf dingbats";font-size:16px;''>And packing: bread,</span><br/> <span style=''line-height:24px;font-family:Calibri, "zapf dingbats";font-size:16px;''>3. Featuring :</span></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''line-height:24px;font-family:Calibri, "zapf dingbats";font-size:16px;''>Super high transparency and glossy,Super high tensile strength</span><br/> <span style=''line-height:24px;font-family:Calibri, "zapf dingbats";font-size:16px;''>Super high grease barrier, Excellent ink and coating adhesion</span><br/> <span style=''line-height:24px;font-family:Calibri, "zapf dingbats";font-size:16px;''>Low static electricity,Superior thickness uniformity</span><br/> <span style=''line-height:24px;font-family:Calibri, "zapf dingbats";font-size:16px;''>Smoothness of the vertical section and much compact of film rolls winding</span></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''line-height:24px;font-family:Calibri, "zapf dingbats";font-size:16px;''>4. Technology data: </span><br/> <span style=''line-height:24px;font-family:Calibri, "zapf dingbats";font-size:16px;''>TYPICAL VALUES AND PHYSICAL PROPERTIES </span></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font