INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (58, 232, 'BOPP Soft Touch Velvet Thermal Lamination Film', '../upload/image/20180928/20180928234433_99483.jpg', '<p></p><table border="0" cellpadding="0" cellspacing="1" class="ke-zeroborder" style=''margin:0px auto;color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;'' width="100%"> <tbody> <tr> <td align="center" class="line_buttom_hui_xuxian" colspan="2" valign="middle"> <div class="Pro_BigImage" style="background:#FFFFFF;text-align:center;"> <img alt="Click to view the next picture" src="../images/no-photo.png"/> </div> </td> </tr> <tr> <td colspan="2" valign="middle"> Product name :<strong>BOPP Soft Touch Velvet Thermal Lamination Film</strong> </td> </tr> <tr> <td colspan="2" valign="middle"> Item :<strong>3919109900</strong> </td> </tr> <tr> <td colspan="2" valign="middle"> Details : </td> </tr> <tr> <td class="line_buttom_hui_xuxian" colspan="2"> <div class="hangju" style="padding:3px;"> <img alt="QQ20141209152648.jpg" src="http://kfdown.s.aliimg.com/kf/HTB171qIHXXXXXbWXVXXq6xXFXXXk/221290553/HTB171qIHXXXXXbWXVXXq6xXFXXXk.jpg" style="border:0px currentColor;"/><img alt="QQ20141209152720.jpg" src="http://kfdown.s.aliimg.com/kf/HTB1GiyNHXXXXXXZXFXXq6xXFXXXk/221290553/HTB1GiyNHXXXXXXZXFXXq6xXFXXXk.jpg" style="border:0px currentColor;"/><img alt="QQ20141209152829.jpg" src="http://kfdown.s.aliimg.com/kf/HTB1pq5SHXXXXXc0XXXXq6xXFXXX6/221290553/HTB1pq5SHXXXXXc0XXXXq6xXFXXX6.jpg" style="border:0px currentColor;"/><img alt="QQ20141209152838.jpg" src="http://kfdown.s.aliimg.com/kf/HTB1Ha5IHXXXXXchXVXXq6xXFXXXq/221290553/HTB1Ha5IHXXXXXchXVXXq6xXFXXXq.jpg" style="border:0px currentColor;"/><img alt="QQ20141209152924.jpg" src="http://kfdown.s.aliimg.com/kf/HTB1HWaTHXXXXXb1XXXXq6xXFXXXx/221290553/HTB1HWaTHXXXXXb1XXXXq6xXFXXXx.jpg" style="border:0px currentColor;"/><img alt="IMG_20141121_130430.jpg" src="http://kfdown.s.aliimg.com/kf/HTB17LmSHXXXXXcUXXXXq6xXFXXXN/221290553/HTB17LmSHXXXXXcUXXXXq6xXFXXXN.jpg" style="border:0px currentColor;"/> <div id="ali-anchor-description" style="font-family:arial, helvetica, sans-serif;"> <p></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>Instructions for Soft-Touch Film</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>is designed to offer soft tactility velvet touch to printed substrate. It can be attached to any surface smooth paper printed by various printing types. Its velvet surface is suitable for UV spot coating, foil stamping to enhance its aesthetic look.</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>General Applications</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>·High-value Packaging</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>·User manuals</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>·Promotion stuff</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>·Leaflets</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>Usage Method</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>1) for laminating soft-touch film</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;font-family:Calibri, "background-color:#FFFF00;''><span style="line-height:normal;">Laminating temperature: 120 </span><span style="line-height:normal;">℃</span><span style="line-height:normal;"> ~130 </span><span style="line-height:normal;">℃</span></span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>2) for glue-coating soft-touch film</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>Check the gloss surface energy to insure that it is suitable for glue coating. Choose suitable glue and flatten the film to get perfect attaching effect.</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>Attention</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''><img alt="QQ20141209174853.jpg" src="http://kfdown.s.aliimg.com/kf/HTB1OvOSHXXXXXcSXXXXq6xXFXXXd/221290553/HTB1OvOSHXXXXXcSXXXXq6xXFXXXd.jpg" style="border:0px currentColor;"/><img alt="QQ20141209174917.jpg" src="http://kfdown.s.aliimg.com/kf/HTB19pGNHXXXXXXGXFXXq6xXFXXXU/221290553/HTB19pGNHXXXXXXGXFXXq6xXFXXXU.jpg" style="border:0px currentColor;"/><img alt="QQ20141209174935.jpg" src="http://kfdown.s.aliimg.com/kf/HTB1l.OOHXXXXXX2XpXXq6xXFXXXH/221290553/HTB1l.OOHXXXXXX2XpXXq6xXFXXXH.jpg" style="border:0px currentColor;"/></span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>Film handling It is strictly prohibited to roll film with tilting angle or make the film contact with hard objects.</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;font-family:Calibri, "background-color:#FFFF00;''><span style="line-height:normal;">Storage conditions The film should be overhead laying and stored in ventilating and dry place with temperature below 35 </span><span style="line-height:normal;">℃</span><span style="line-height:normal;">and relative humidity lower than 60%; Keep the film away from sources of heat.</span></span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>Shelf life 6 months</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>Surface treatment The surface energy may decrease because of inappropriate storage or out of shelf-life. Corona treatment can be employed to make the surface suitable for use.</span></strong></span></p> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>Technical Data</span></strong></span></p> <table border="0" cellpadding="0" class="aliDataTable mceItemTable ke-zeroborder" style="border-collapse:collapse;"> <tbody> <tr> <td style="font-family:Verdana, Arial, Helvetica, sans-serif;"> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>items</span></strong></span></p> </td> <td style="font-family:Verdana, Arial, Helvetica, sans-serif;"> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>data</span></strong></span></p> </td> <td style="font-family:Verdana, Arial, Helvetica, sans-serif;"> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>Testing method</span></strong></span></p> </td> </tr> <tr> <td style="font-family:Verdana, Arial, Helvetica, sans-serif;"> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>Thickness / μm</span></strong></span></p> </td> <td style="font-family:Verdana, Arial, Helvetica, sans-serif;"> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>18±5%</span></strong></span></p> </td> <td style="font-family:Verdana, Arial, Helvetica, sans-serif;"> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>GB/T 6672</span></strong></span></p> </td> </tr> <tr> <td style="font-family:Verdana, Arial, Helvetica, sans-serif;"> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;line-height:normal;font-family:Calibri, "background-color:#FFFF00;''>White spot / 33cm*33cm</span></strong></span></p> </td> <td style="font-family:Verdana, Arial, Helvetica, sans-serif;"> <p><span style="line-height:36px;font-size:24px;"><strong><span style=''color:#FF0000;font-family:Calibri, "background-color:#FFFF00;''><span style="line-height:normal;">≤8</span><span style="line-height:normal;">(</span><span style="line-height:normal;">Φ≤0.3mm</span><span style="line-height:normal;">)</span><span style="line-