INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (58, 236, 'BOPP Thermal Lamination Film ( glossy / matte ) which is BOPP clear film coated with EVA .', '../upload/image/20180928/20180928231824_36185.jpg', '<p></p><div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span>BOPP Thermal Film ( glossy / matte )</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span>BOPP Thermal Lamination Film ( glossy / matte ) which is BOPP clear film coated with EVA .</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span>Spec. :</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span>1.) Jumbo roll sizes :<br/> Total Thickness :22-33UM (Mic.)<br/> Film thickness : 10,12,15,18,20 UM (Mic.)</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span>Width :325-1200MM</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span>Length :3000M (2000M,4000M,6000M,9000M).</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span>Inner core :76MM ,152MM</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span>2.) Mini-roll sizes :<br/> Total Thickness :22-33UM (Mic.)<br/> Film thickness : 10,12,15,18,20 UM (Mic.)</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span>Width :325-1200MM</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span>Length :100M,120M,150M,200M</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span>Inner core :1.5” ,1.8” 2.0” 3” (Inches)</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span>Applications: Laminate<span style="color:black;">the surface of</span><span style="color:black;">Books, catalogs, samples, posters, printed paper, Food, medicines, cosmetics, gifts, wine boxes and other packaging film ,Drawings, documents, ads, pictures, display boards, etc.<br/> </span></span></span> </div>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (58, 233, 'KPET (BOPET film, coated on both sides heat sealing barrier PVDC coating)', '../upload/image/20180826/20180826183520_89617.jpg', '<p></p><div id="right_main"> <table border="0" cellpadding="0" cellspacing="1" style="margin:0px auto;" width="100%"> <tbody> <tr> <td class="line_buttom_hui_xuxian" colspan="2"> <div class="hangju" style="padding:3px;"> <strong><span style=''color:#FF0000;line-height:36px;font-family:Calibri, "zapf dingbats";font-size:24px;background-color:#FFFF00;''>PVDC coating film -K film (BOPP/BOPA/BOPET film coated PVDC)</span></strong> <p style="font-family:arial, helvetica, sans-serif;"> <strong><span style=''color:#FF0000;line-height:36px;font-family:Calibri, "zapf dingbats";font-size:24px;background-color:#FFFF00;''><img alt="IMG_20140701_104145.jpg" src="http://kfdown.s.aliimg.com/kf/HTB1xtbnFVXXXXbdXXXXq6xXFXXX2/221290553/HTB1xtbnFVXXXXbdXXXXq6xXFXXX2.jpg" style="border:0px currentColor;"/></span></strong></p> <p style="font-family:arial, helvetica, sans-serif;"> <strong><span style=''color:#FF0000;line-height:36px;font-family:Calibri, "zapf dingbats";font-size:24px;background-color:#FFFF00;''>1 Types for PVDC coating film -K film</span></strong><br/> <strong><span style=''color:#FF0000;line-height:36px;font-family:Calibri, "zapf dingbats";font-size:24px;background-color:#FFFF00;''>PVDC coating film -K film (BOPP/BOPA/BOPET film coated PVDC)</span></strong><br/> <strong><span style=''color:#FF0000;line-height:36px;font-family:Calibri, "zapf dingbats";font-size:24px;background-color:#FFFF00;''>KOPP (BOPP film, coated on both sides heat sealing barrier PVDC coating)</span></strong><br/> <strong><span style=''color:#FF0000;line-height:36px;font-family:Calibri, "zapf dingbats";font-size:24px;background-color:#FFFF00;''>KPA (BOPA film, coated on both sides heat sealing barrier PVDC coating)</span></strong><br/> <strong><span style=''color:#FF0000;line-hei